create or replace function public.sync_stripe_subscription_entitlement(p_user_id uuid, p_plan_code text, p_status text) returns void language plpgsql security definer set search_path=public as $function$ begin if p_status in ('active','trialing','past_due') then insert into public.account_service_entitlements(account_user_id,service_tier,location_limit,fleet_enabled,enterprise_fleet_enabled) values(p_user_id,p_plan_code,case when p_plan_code='premium' then 50 when p_plan_code='family' then 100 else null end,p_plan_code in ('fleet','business_fleet','enterprise','business_enterprise'),p_plan_code in ('enterprise','business_enterprise')) on conflict (account_user_id) do update set service_tier=excluded.service_tier,location_limit=excluded.location_limit,fleet_enabled=excluded.fleet_enabled,enterprise_fleet_enabled=excluded.enterprise_fleet_enabled,updated_at=now(); else delete from public.account_service_entitlements where account_user_id=p_user_id; end if; end; $function$;
revoke all on function public.sync_stripe_subscription_entitlement(uuid,text,text) from public,anon,authenticated;
grant execute on function public.sync_stripe_subscription_entitlement(uuid,text,text) to service_role;
